@pytest.mark.parametrize('Cls', GRADIENT_BOOSTING_ESTIMATORS)
@pytest.mark.parametrize('random_state', [0, np.random.RandomState(0), None])
def test_warm_start_early_stopping_validation_data(Cls, random_state):
    # A mutable RNG must not move training samples into validation on refit.
    X, y = make_classification(n_samples=100, random_state=0)
    sample_weight = np.arange(1, X.shape[0] + 1, dtype=np.float64)
    splits = []

    def monitor(i, estimator, local_variables):
        if i in (0, 3):
            splits.append(tuple(local_variables[name].copy() for name in
                                ('X', 'X_val', 'y', 'y_val', 'sample_weight',
                                 'sample_weight_val')))

    est = Cls(n_estimators=3, warm_start=True, n_iter_no_change=20,
              subsample=0.5, random_state=random_state)
    est.fit(X, y, sample_weight=sample_weight, monitor=monitor)
    est.set_params(n_estimators=6)
    est.fit(X, y, sample_weight=sample_weight, monitor=monitor)

    assert len(splits) == 2
    for first_fit, second_fit in zip(*splits):
        assert_array_equal(first_fit, second_fit)


